/** Returns the first cycle found by the specified DFS, or null. */
export function findCycle(g) {
  const state = new Map()
  const stack = []
  function visit(n) {
    state.set(n, 1)
    stack.push(n)
    for (const d of g.deps.get(n)) {
      const s = state.get(d)
      if (s === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (!s) {
        const c = visit(d)
        if (c) return c
      }
    }
    stack.pop()
    state.set(n, 2)
    return null
  }
  for (const n of g.names) {
    if (!state.get(n)) {
      const c = visit(n)
      if (c) return c
    }
  }
  return null
}

/** Computes start, finish, depth per task and the unlimited-worker total. */
export function analyze(g) {
  const start = new Map(), finish = new Map(), depth = new Map()
  let total = 0n
  function visit(n) {
    if (finish.has(n)) return
    let s = 0n, d = 0
    for (const dep of g.deps.get(n)) {
      visit(dep)
      if (finish.get(dep) > s) s = finish.get(dep)
      d = Math.max(d, depth.get(dep) + 1)
    }
    start.set(n, s)
    finish.set(n, s + g.cost.get(n))
    depth.set(n, d)
    if (finish.get(n) > total) total = finish.get(n)
  }
  for (const n of g.names) visit(n)
  return { start, finish, depth, total }
}

/** Simulates the list-scheduling rule on the given number of workers. */
export function pack(g, info, workers) {
  const dependents = new Map(g.names.map((n) => [n, []]))
  for (const n of g.names) for (const d of g.deps.get(n)) dependents.get(d).push(n)
  const prio = new Map()
  const calc = (n) => {
    if (prio.has(n)) return prio.get(n)
    let best = 0n
    for (const m of dependents.get(n)) { const p = calc(m); if (p > best) best = p }
    prio.set(n, best + g.cost.get(n))
    return prio.get(n)
  }
  for (const n of g.names) calc(n)

  const lanes = Array.from({ length: Math.min(workers, 1e7) }, () => [])
  const freeAt = new Array(lanes.length).fill(0n)
  const done = new Map()
  const pending = new Set(g.names)
  let t = 0n
  let makespan = 0n
  for (;;) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const n of pending) {
        if (!g.deps.get(n).every((d) => done.has(d) && done.get(d) <= t)) continue
        if (pick === null || prio.get(n) > prio.get(pick) || (prio.get(n) === prio.get(pick) && n < pick)) pick = n
      }
      if (pick === null) break
      pending.delete(pick)
      const f = t + g.cost.get(pick)
      done.set(pick, f)
      freeAt[w] = f
      lanes[w].push({ name: pick, start: t, finish: f })
      if (f > makespan) makespan = f
    }
    if (pending.size === 0) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
    t = next
  }
  return { lanes, makespan }
}
