export class GraphError extends Error {}

const NAME = /^[A-Za-z0-9_.-]+$/

/** Parses the input text into { names (sorted), cost, deps (name -> sorted array) }. */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cost = new Map()
  const depLines = []
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    const n = i + 1
    if (w[0] === 'task') {
      if (w.length !== 3) throw new GraphError(`line ${n}: expected task <name> <cost>`)
      if (!NAME.test(w[1])) throw new GraphError(`line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new GraphError(`line ${n}: cost must be a non-negative integer`)
      if (cost.has(w[1])) throw new GraphError(`line ${n}: task ${w[1]} is declared twice`)
      cost.set(w[1], BigInt(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new GraphError(`line ${n}: expected dep <name> <dependency>...`)
      depLines.push(w.slice(1))
    } else {
      throw new GraphError(`line ${n}: unknown directive ${w[0]}`)
    }
  })
  const deps = new Map([...cost.keys()].map((k) => [k, new Set()]))
  for (const names of depLines) {
    for (const nm of names) if (!cost.has(nm)) throw new GraphError(`unknown task ${nm}`)
  }
  for (const [name, ...ds] of depLines) for (const d of ds) deps.get(name).add(d)
  const sorted = new Map()
  for (const [k, s] of deps) sorted.set(k, [...s].sort())
  return { names: [...cost.keys()].sort(), cost, deps: sorted }
}
